codeExample.bad:
// A multi-step checkout form times out after 10 minutes even with an
// extend option, discarding entered data if the user doesn't act
let checkoutTimer = setTimeout(() => {
  discardCheckoutSession();
}, 600000);

codeExample.good:
// No time limit imposed on completing checkout; a session is kept
// alive as long as the user is actively working, with no countdown
// pressuring completion within a fixed window
function onUserActivity() {
  refreshSessionKeepAlive();
}
document.addEventListener('input', onUserActivity);
document.addEventListener('click', onUserActivity);
